<script setup>
import { onMounted, ref } from 'vue';
import { apiFetch, listFrom } from '../../app/services/api';
import ProductCard from '../components/ProductCard.vue';
const props = defineProps({ vendorId: String }); const vendor = ref(null); const products = ref([]); const following = ref(false);
onMounted(async () => { if (!props.vendorId) return; try { const [vendorResponse, productResponse] = await Promise.all([apiFetch(`/vendors/${props.vendorId}`), apiFetch(`/vendors/${props.vendorId}/products`)]); vendor.value = vendorResponse.vendor || vendorResponse; products.value = listFrom(productResponse, ['products']); const followed = await apiFetch('/users/following').catch(() => ({})); following.value = listFrom(followed).some((item) => Number(item.id) === Number(props.vendorId)); } catch { vendor.value = null; } });
async function toggleFollow() { if (!localStorage.getItem('token') && !localStorage.getItem('localcart-token')) { window.location.href = 'index.html?view=login'; return; } await apiFetch(`/users/following/${props.vendorId}`, { method: following.value ? 'DELETE' : 'POST' }); following.value = !following.value; }
</script>
<template><section v-if="vendor" class="content vendor-page"><div class="store-banner" :style="{ backgroundImage: `url(${vendor.cover_image || vendor.cover || 'https://images.unsplash.com/photo-1494526585095-c41746248156?w=1200&q=70'})` }"></div><div class="store-heading"><div class="vendor-logo">{{ (vendor.logo_text || vendor.name || 'LC').slice(0,2).toUpperCase() }}</div><div><p class="eyebrow">{{ vendor.category || 'Local vendor' }}</p><h1>{{ vendor.name }}</h1><p>{{ vendor.location || 'South Africa' }}</p></div><button class="btn-primary" type="button" @click="toggleFollow">{{ following ? 'Following' : '+ Follow' }}</button></div><p class="vendor-description">{{ vendor.about || vendor.description || 'This vendor has not added a storefront bio yet.' }}</p><h2 class="section-title">Products</h2><div class="products"><ProductCard v-for="product in products" :key="product.id || product.product_id" :product="product" /></div></section><section v-else class="empty-state">Vendor not found.</section></template>